#!/bin/bash
S=${S:-/puffertank/pufferlib}
# vec binary on the FORK engine with the C derivations wrapped around every hook (validation harness)
cd $S
clang -O0 -g -fPIC -c -I. -Ivendor/fast-nle/include -Ivendor/fast-nle/build/_deps/deboost_context-src/include $S/scripts/nle_stock/nh_fork_harness.c -o $S/scripts/nle_stock/nh_fork_harness.o || exit 1
ccache /usr/local/cuda/bin/nvcc -O2 --threads 0 -arch=native -std=c++17 -I. -Isrc -Iocean/nethack -Ivendor -I./raylib-5.5_linux_amd64/include -I./src -I./vendor -I./vendor/fast-nle/include -I./vendor/fast-nle/build/_deps/deboost_context-src/include -I/usr/local/cuda/include -I/usr/local/cuda/include/cccl -I/usr/include -Iraylib-5.5_linux_amd64/include '-DENV_HEADER="ocean/nethack/nethack.h"' -DENV_NAME=nethack '-DPUFFER_ENV_NAME="nethack"' -DPUFFERLIB_BUILD_MAIN -Xcompiler=-DPLATFORM_DESKTOP -Xcompiler=-fopenmp -Xcompiler=-Wno-narrowing --diag-suppress=2361 -DPUFFER_NETHACK -DPUFFER_NETHACK src/pufferl.cu $S/scripts/nle_stock/nh_fork_harness.o  -Xlinker --wrap=nle_start -Xlinker --wrap=nle_step -Xlinker --wrap=nle_obs_refresh -Xlinker --wrap=nle_end -Xlinker --wrap=nle_identity -Xlinker --wrap=nle_terrain_underfoot -Xlinker --wrap=nle_food_underfoot -Xlinker --wrap=nle_container_at -Xlinker --wrap=nle_shop_price -Xlinker --wrap=nle_inside_shop -Xlinker --wrap=nle_peaceful_at -Xlinker --wrap=nle_spells -Xlinker --wrap=nle_lnc_bits -Xlinker --wrap=nle_weight -Xlinker --wrap=nle_intrinsics -Xlinker --wrap=nle_cast_blocked -Xlinker --wrap=nle_path_drain -Xlinker --wrap=nle_discoveries raylib-5.5_linux_amd64/lib/libraylib.a -L/usr/local/cuda/lib64 -L/usr/lib/x86_64-linux-gnu -L/tmp/claude-0/-puffertank-pufferlib/a05ccdbb-322b-4b8a-8e6b-e69d4a0642b6/scratchpad/wt_gate/vendor/fast-nle/build -lnethack -Xlinker -rpath -Xlinker /tmp/claude-0/-puffertank-pufferlib/a05ccdbb-322b-4b8a-8e6b-e69d4a0642b6/scratchpad/wt_gate/vendor/fast-nle/build -ldl -lcudart -lnccl -lnvidia-ml -lcublas -lcusolver -lcurand -lm -lpthread -lomp5 -lGL -o puffer_nethack_harness
